                Администратор клиники сразу связывается с вами
              </li>
            </m.ul>
          </div>

          <m.figure {...fade(0.2)} className="relative min-w-0">
            <div className="overflow-hidden rounded-lg">
              <img
                src={photoSrc}
                alt={photoAlt}
                width={800}
                height={533}
                loading="eager"
                className="aspect-3/2 w-full rounded-lg object-cover"
