// Hero «collage»: the offer in a quiet left column with a small note, on the right two photos of the clinic —
// the cabinet large and the doctor with a patient small; on phones text first, then photos.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Image = { src: string; alt: string };

export type HeroCollageProps = {
  eyebrow: string;
  title: string;
  subtitle: string;
  note: string;
  image: Image;
  secondaryImage: Image;
  photoCaption: string;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

/** Calm entrance: a single fade, only with the lively profile and without reduced motion. */
function useFade() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  if (!(lively && !reduce)) return () => ({});
  return (step: number) => ({
    initial: { opacity: 0 },
    animate: { opacity: 1 },
    transition: { duration: 0.5, delay: step * 0.08 },
  });
}

export default function HeroCollage({
  eyebrow,
  title,
  subtitle,
  note,
  image,
  secondaryImage,
  photoCaption,
  wzId,
}: HeroCollageProps) {
  const fade = useFade();
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="min-w-0 lg:col-span-5">
            <m.p {...fade(0)} className="text-small font-bold tracking-wide text-muted-foreground">
              {eyebrow}
            </m.p>
            <m.h1
              {...fade(1)}
              className="mt-3 font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            <m.p {...fade(2)} className="mt-5 max-w-text text-lead text-pretty text-muted-foreground">
              {subtitle}
            </m.p>
            <m.div {...fade(3)} className="mt-8">
              <a href="#form" data-testid="wz-hero-primary" className={primaryClass}>
                Оставить заявку
              </a>
            </m.div>
            <p className="mt-5 text-small text-muted-foreground">{note}</p>
          </div>
          <div className="min-w-0 lg:col-span-7">
            <div className="grid gap-4 sm:grid-cols-5 sm:items-start">
              <m.div {...fade(2)} className="min-w-0 sm:col-span-3">
                <img
                  src={image.src}
                  srcSet={srcSetOf(image.src)}
                  sizes="(min-width: 1024px) 45vw, 100vw"
                  alt={image.alt}
                  fetchPriority="high"
                  className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
                />
              </m.div>
              <m.figure {...fade(3)} className="min-w-0 sm:col-span-2">
                <img
                  src={secondaryImage.src}
                  srcSet={srcSetOf(secondaryImage.src)}
                  sizes="(min-width: 1024px) 25vw, 60vw"
                  alt={secondaryImage.alt}
                  loading="lazy"
                  className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
                />
                <figcaption className="mt-3 text-small text-muted-foreground">{photoCaption}</figcaption>
              </m.figure>
            </div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

// Two-part section: «Why us» as large numbered entries on the left, «How it works» as a tight step list
// on a card background — dense and airy at once. Calm tone, one h2 per part.
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Item = { title: string; text?: string };
type Link = { label: string; href: string };

export type WhyStepsProps = {
  whyTitle: string;
  whyItems: Item[];
  stepsTitle: string;
  steps: string[];
  action: Link;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

function useFade() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  if (!(lively && !reduce)) return () => ({});
  return (step: number) => ({
    initial: { opacity: 0 },
    animate: { opacity: 1 },
    transition: { duration: 0.5, delay: step * 0.08 },
  });
}

export default function WhySteps({ whyTitle, whyItems, stepsTitle, steps, action, wzId }: WhyStepsProps) {
  const fade = useFade();
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="WhySteps" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page gap-12 px-gutter py-section lg:grid-cols-12 lg:gap-16">
          <div className="min-w-0 lg:col-span-7">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{whyTitle}</h2>
            <ul className="mt-8 border-t-2 border-foreground">
              {whyItems.map((item, i) => (
                <m.li
                  key={item.title}
                  {...fade(i)}
                  className="grid gap-x-6 gap-y-1 border-b border-border py-6 sm:grid-cols-12"
                >
                  <span
                    aria-hidden="true"
                    className="font-display text-h3 font-bold tabular-nums text-muted-foreground sm:col-span-1"
                  >
                    {String(i + 1).padStart(2, "0")}
                  </span>
                  <div className="min-w-0 sm:col-span-11">
                    <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{item.title}</h3>
                    {item.text ? <p className="mt-2 max-w-text text-body text-muted-foreground">{item.text}</p> : null}
                  </div>
                </m.li>
              ))}
            </ul>
          </div>
          <div className="min-w-0 lg:col-span-5">
            <div className="rounded-lg bg-card p-8 text-card-foreground">
              <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{stepsTitle}</h2>
              <ol className="mt-6 flex flex-col gap-5">
                {steps.map((step, i) => (
                  <li key={step} className="flex items-baseline gap-4">
                    <span className="inline-flex min-w-6 shrink-0 items-center justify-center rounded-full bg-primary font-display text-small font-bold tabular-nums text-primary-foreground">
                      {i + 1}
                    </span>
                    <p className="text-body text-pretty wrap-break-word">{step}</p>
                  </li>
                ))}
              </ol>
              <a href={action.href} className={`mt-8 ${primaryClass}`}>
                {action.label}
              </a>
            </div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

// FAQ as a short question list on the left, a photo of the clinic hall with a call-to-action on the right.
// One h2 for questions, the CTA is a lead-in to the form below.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Item = { question: string; answer: string };
type Image = { src: string; alt: string };
type Link = { label: string; href: string };

export type FaqCtaProps = {
  title: string;
  items: Item[];
  ctaTitle: string;
  action: Link;
  photo: Image;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function FaqCta({ title, items, ctaTitle, action, photo, wzId }: FaqCtaProps) {
  return (
    <section data-wz-component="FaqCta" data-wz-id={wzId} className="bg-background font-sans text-foreground">
      <div className="mx-auto grid w-full max-w-page gap-12 px-gutter py-section lg:grid-cols-12 lg:gap-16">
        <div className="min-w-0 lg:col-span-6">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          <ul className="mt-8 border-t border-border">
            {items.map((item) => (
              <li key={item.question} className="border-b border-border py-6">
                <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{item.question}</h3>
                <p className="mt-2 max-w-text text-body text-muted-foreground">{item.answer}</p>
              </li>
            ))}
          </ul>
        </div>
        <div className="min-w-0 lg:col-span-6">
          <img
            src={photo.src}
            srcSet={srcSetOf(photo.src)}
            sizes="(min-width: 1024px) 50vw, 100vw"
            alt={photo.alt}
            loading="lazy"
            className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
          />
          <div className="mt-8 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{ctaTitle}</h2>
            <a href={action.href} className={primaryClass}>
              {action.label}
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}

