// CTA band: a calm inverse band with the contact phone as the main action; the photo of the reception desk
// sits to the right, the offer and phone to the left. On phones the text comes first.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Image = { src: string; alt: string };

export type CtaBandProps = {
  title: string;
  lead?: string;
  phone: string;
  action: { label: string; href: string };
  note?: string;
  image: Image;
  wzId?: string;
};

const bandLinkClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-inverse-foreground px-6 text-center text-body font-bold text-inverse transition-colors duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";
const telLinkClass =
  "font-display text-h2 font-bold text-inverse-foreground underline decoration-2 underline-offset-8 wrap-break-word transition-colors duration-200 hover:opacity-80";

export default function CtaBand({ title, lead, phone, action, note, image, wzId }: CtaBandProps) {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const enter =
    lively && !reduce
      ? {
          initial: { opacity: 0, y: 12 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Cta" data-wz-id={wzId} className="bg-inverse font-sans text-inverse-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <m.div {...enter} className="min-w-0 lg:col-span-6">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
            {lead ? (
              <p className="mt-4 max-w-text text-lead text-pretty opacity-90">{lead}</p>
            ) : null}
            <a href={`tel:${phone.replace(/[^\d+]/g, "")}`} className={`mt-6 inline-block ${telLinkClass}`}>
              {phone}
            </a>
            <div className="mt-8">
              <a href={action.href} className={bandLinkClass}>
                {action.label}
              </a>
            </div>
            {note ? <p className="mt-5 text-small opacity-80">{note}</p> : null}
          </m.div>
          <m.div {...enter} className="min-w-0 lg:col-span-6">
            <img
