              >
                {secondaryAction.label}
              </a>
            </m.div>

            <m.dl {...fade(0.4)} className="mt-10 flex items-center gap-4 border-t border-border pt-6">
              <dt className="font-display text-h2 text-foreground">{stat.value}</dt>
              <dd className="text-small text-muted-foreground">{stat.label}</dd>
            </m.dl>
          </div>

          <m.div
            {...(reduce ? {} : ready ? { initial: { opacity: 0, scale: 0.97 }, animate: { opacity: 1, scale: 1 }, transition: { duration: 0.7, delay: 0.15, ease: "easeOut" as const } } : {})}
