// FAQ: a quiet accordion of questions; one item is enough when there is one fact.
import { useState } from "react";

export type FaqQuietProps = {
  title: string;
  items: { question: string; answer: string }[];
  wzId?: string;
};

export default function FaqQuiet({ title, items, wzId }: FaqQuietProps) {
  const [open, setOpen] = useState(0);
  return (
    <section data-wz-id={wzId} className="bg-card font-sans text-card-foreground">
      <div className="mx-auto grid w-full max-w-page gap-10 px-gutter py-section lg:grid-cols-12">
        <h2 className="min-w-0 font-display text-h1 font-bold text-balance wrap-break-word lg:col-span-4">
          {title}
        </h2>
        <div className="min-w-0 lg:col-span-8">
          <ul className="border-t border-border">
            {items.map((item, i) => {
              const isOpen = open === i;
              return (
                <li key={item.question} className="border-b border-border">
                  <button
                    type="button"
                    aria-expanded={isOpen}
                    onClick={() => setOpen(isOpen ? -1 : i)}
                    className="flex min-h-11 w-full items-center justify-between gap-4 py-5 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
