}

// «Why us»: airy section — title and a two-column list of numbered points on a card background, photo beside on desktop.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Image = { src: string; alt: string };
type Point = { title: string; text: string };

export type WhyClinicProps = {
