};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";
const phoneClass =
  "inline-flex min-h-11 min-w-11 items-center text-body font-bold text-foreground underline decoration-primary decoration-2 underline-offset-4 transition-colors duration-200 hover:decoration-foreground";

export default function CtaBand({ title, action, phone, phoneHref, note }: CtaBandProps) {
  const reduce = useReducedMotion();
