// Первый экран «split»: оффер слева (заголовок, пояснение, одна кнопка, практичная строка), фото справа;
// на телефоне текст, затем фото. Композиция на токенах дизайн-системы.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroSplitProps = {
  title: string;
  lead?: string;
  action: Link;
  note?: string;
  image: Image;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

/** Вход первого экрана: один раз, только с живым профилем движения. */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 12 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.05, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function HeroSplit({ title, lead, action, note, image, wzId }: HeroSplitProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(title);
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="min-w-0 lg:col-span-6">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            {lead ? (
              <m.p {...enter(1)} className="mt-5 max-w-text text-lead text-pretty text-muted-foreground">
                {lead}
              </m.p>
            ) : null}
            <m.div {...enter(2)} className="mt-8 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
              <a href={action.href} data-testid="wz-hero-primary" className={primaryClass}>
                {action.label}
              </a>
            </m.div>
            {note ? <p className="mt-5 text-small text-muted-foreground">{note}</p> : null}
          </div>
          <m.div {...enter(1)} className="min-w-0 lg:col-span-6">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

// Порядок записи: фото слева и шаги справа с описаниями из слов владельца; практичная строка внизу.
type Image = { src: string; alt: string };
type Step = { title: string; text?: string };

export type StepsProps = {
  title: string;
  items: Step[];
  note?: string;
  image: Image;
  wzId?: string;
};

export default function Steps({ title, items, note, image, wzId }: StepsProps) {
  return (
    <section className="bg-card font-sans text-card-foreground">
      <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
        <div className="min-w-0 order-2 lg:order-1 lg:col-span-5">
          <img
            src={image.src}
            alt={image.alt}
            loading="lazy"
            className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
          />
        </div>
        <div className="min-w-0 order-1 lg:order-2 lg:col-span-7">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          <ol className="mt-10">
            {items.map((step, i) => (
              <li
                key={step.title}
                className="flex gap-6 border-b border-border py-6 first:border-t-0 first:pt-0 md:py-8"
              >
                <span
                  aria-hidden="true"
                  className="mt-1 h-3 w-3 shrink-0 rounded-sm bg-primary"
                />
                <div className="min-w-0">
                  <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                  {step.text ? <p className="mt-2 max-w-text text-body text-muted-foreground">{step.text}</p> : null}
                </div>
                <span className="ml-auto hidden shrink-0 font-display text-h2 font-bold text-muted-foreground tabular-nums sm:block">
                  {i + 1}
                </span>
              </li>
            ))}
          </ol>
          {note ? <p className="mt-8 max-w-text text-lead text-pretty text-muted-foreground">{note}</p> : null}
        </div>
      </div>
    </section>
  );
}

// Плотный блок вопросов и призыва: слева заголовок-вопрос и кнопка к форме, справа вопрос-ответ
// и фото стойки администратора; чередует ритм страницы после шагов.
type Link = { label: string; href: string };
type Image = { src: string; alt: string };
type Item = { question: string; answer: string };

export type FaqCtaProps = {
  title: string;
  items: Item[];
  action: Link;
  image: Image;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function FaqCta({ title, items, action, image, wzId }: FaqCtaProps) {
  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-12 lg:gap-14">
          <div className="min-w-0 lg:col-span-5">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
            <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">
              Оставьте заявку — администратор ответит на вопросы и подберёт время приёма.
            </p>
            <a href={action.href} className={`mt-8 ${primaryClass}`}>
              {action.label}
            </a>
          </div>
          <div className="min-w-0 lg:col-span-7">
            <ul className="border-t-2 border-foreground">
              {items.map((item) => (
                <li key={item.question} className="border-b border-border py-6">
                  <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{item.question}</h3>
                  <p className="mt-2 max-w-text text-body text-muted-foreground">{item.answer}</p>
                </li>
              ))}
            </ul>
            <img
              src={image.src}
              alt={image.alt}
              loading="lazy"
              className="mt-8 aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </div>
        </div>
      </div>
    </section>
  );
}

